 function renderDashboard(current,data){const box=current.querySelector('#zain-everything-dashboard');if(!box||!data.dashboard)return;const d=data.dashboard,c=d.counts,stamp=v=>v?new Date(v).toLocaleString():'لم يسجل بعد',open=box.querySelector('details')?.open;box.textContent='';const add=text=>{const p=document.createElement('p');p.textContent=text;box.append(p);};add('الحالة: '+(!d.enabled?'المتابعة متوقفة':d.paused?'بانتظار العمل الجاري بالخادم':d.busy?data.status.phase:d.allReady?'اكتملت التهيئة — انتظار دورة المتابعة التالية':'المتابعة تعمل — لم تكتمل تهيئة جميع المسارات'));add('المرجع جاهز: '+c.ready+' من '+c.total+' — قيد التهيئة: '+c.initializing+' — لم تبدأ: '+c.notStarted+' — بلا نتائج: '+c.waiting+' — أخطاء: '+c.error);add('الجاهز يشمل المسارات التي اكتمل مرجعها حتى إن حدث خطأ اتصال لاحقًا.');if(d.activePath)add('المسار الجاري: '+d.activePath);add('آخر فحص ناجح: '+stamp(d.lastSuccess)+' — آخر إضافة ناجحة: '+stamp(d.lastAddition));add('الفحص التالي: '+(!d.enabled?'متوقف':d.nextCheck<=Date.now()?'بانتظار دوره وتوفر الخادم':stamp(d.nextCheck)));const details=document.createElement('details');details.open=!!open;const summary=document.createElement('summary');summary.textContent='حالة كل مسار ('+c.total+')';details.append(summary);const names={ready:'جاهز',initializing:'قيد التهيئة',notStarted:'لم يبدأ',waiting:'بانتظار النتائج',error:'تعذر الفحص'};for(const r of d.rows){const line=document.createElement('p');line.style.cssText='padding:8px;border-bottom:1px solid #34415a;overflow-wrap:anywhere';line.textContent=r.name+' — '+r.path+' — '+(r.active?'يعمل الآن — ':'')+names[r.state]+' — المرجع '+(r.ready?'مكتمل':'غير مكتمل')+(r.total!=null?' — تقدم الدورة: '+r.offset+'/'+r.total:'')+' — آخر فحص ناجح: '+stamp(r.lastSuccess)+(r.error?' — '+r.error:'');details.append(line);}box.append(details);}
 function renderEvents(current,data){const box=current.querySelector('#zain-everything-events');if(!box)return;const rows=data.events||[],key=JSON.stringify(rows);if(box.dataset.key===key)return;box.dataset.key=key;box.textContent='';const title=document.createElement('h3');title.textContent='سجل المزامنة التلقائية';const clear=document.createElement('button');clear.type='button';clear.textContent='مسح السجل السابق';clear.style.cssText='margin-inline-start:10px;padding:6px 12px;background:#9f3f4b;color:white;border:0;border-radius:6px;cursor:pointer';clear.onclick=async()=>{clear.disabled=true;try{await api('clearEverythingEvents',{});box.dataset.key='';lastStatus=0;await refreshStatus();}catch(error){clear.textContent=error.message;}finally{clear.disabled=false;}};box.append(title,clear);if(!rows.length){const line=document.createElement('p');line.textContent='لا توجد أحداث متابعة مسجلة بعد.';box.append(line);}for(const event of rows){const line=document.createElement('p');line.style.cssText='padding:8px;border-bottom:1px solid #34415a;white-space:pre-wrap;overflow-wrap:anywhere';line.textContent=(event.createdAt?new Date(event.createdAt*1000).toLocaleString()+' — ':'')+event.msg;if(['warning','error','danger'].includes(event.type))line.style.color='#ffd099';box.append(line);}}
 function renderMissing(current,data){const box=current.querySelector('#zain-everything-missing');if(!box)return;const rows=data.pathChecks||[],empty=rows.filter(r=>r.state==='empty'),waiting=rows.filter(r=>r.state==='unchecked').length,failed=rows.filter(r=>r.state==='error').length;const signature=JSON.stringify([data.enabled,rows]);if(box.dataset.signature===signature)return;box.dataset.signature=signature;box.textContent='';const title=document.createElement('h4');title.textContent='مسارات بلا نتائج مطابقة للمزامنة في Everything ('+empty.length+')';box.append(title);const note=document.createElement('p');note.textContent='هذه القائمة لا تعني أن المسارات غير مضافة إلى Everything. قد يكون المسار مفهرسًا، لكنه فارغ أو لا يحتوي فيديوهات مطابقة للبحث؛ الألعاب والصوتيات وحدها لا تُعتبر حلقات جديدة. راجع نتائج المسار وصيغته والاستثناءات قبل إضافته مجددًا. الفحص هنا يقرأ فهرس Everything، وتُحفظ آخر نتيجة تحقق بعد إعادة التشغيل.';box.append(note);if(empty.length){const download=document.createElement('button');download.textContent='ملف مساعد لإضافة المسارات غير المفهرسة فقط';download.style.cssText='padding:10px 16px;background:#218a64;color:white;border:0;border-radius:8px;cursor:pointer';download.onclick=async()=>{download.disabled=true;try{const result=await api('exportEverythingFolders',{ids:empty.map(r=>r.id)});const url=URL.createObjectURL(new Blob([result.script],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=result.filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);download.textContent='تم تجهيز الملف؛ شغّله على جهاز Everything';}catch(e){download.textContent=e.message;}finally{download.disabled=false;}};box.append(download);}const summary=document.createElement('p');summary.textContent=(!data.enabled?'المتابعة متوقفة؛ فعّلها وحدد المسارات واحفظ الإعدادات. ':'')+'مسارات محددة: '+rows.length+' — بلا نتيجة تحقق محفوظة: '+waiting+' — تعذر فحصها: '+failed;box.append(summary);if(!empty.length){const text=document.createElement('p');text.textContent=waiting||failed?'لم يكتمل التحقق من جميع المسارات بعد.':'لا توجد مسارات بلا نتائج ضمن آخر الفحوصات المتاحة.';box.append(text);}for(const row of empty){const line=document.createElement('div');line.style.cssText='margin:12px 0;padding:10px;background:#101523;border-radius:6px';const label=document.createElement('div');label.textContent=row.name;const input=document.createElement('input');input.readOnly=true;input.value=row.path;input.dir='ltr';input.setAttribute('aria-label','مسار '+row.name);input.style.cssText='width:100%;box-sizing:border-box;background:#182134;color:white;padding:8px;border:1px solid #52617a;margin:6px 0';input.onclick=()=>input.select();const copy=document.createElement('button');copy.textContent='نسخ المسار';copy.onclick=async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(row.path);else{input.focus();input.select();if(!document.execCommand('copy'))throw Error('copy');}copy.textContent='تم النسخ';}catch{input.focus();input.select();copy.textContent='المسار محدد؛ اضغط Ctrl+C';}};const checked=document.createElement('div');checked.textContent=(row.kind==='series'?'لم يُرجع بحث الفيديوهات نتائج مطابقة. ':'لم يُرجع بحث هذا المسار نتائج مطابقة. ')+(row.checkedAt?'آخر تحقق: '+new Date(row.checkedAt).toLocaleString():'');line.append(label,input,checked,copy);box.append(line);}}
 async function refreshStatus(){if(!host?.isConnected||statusBusy||Date.now()-lastStatus<2000)return;statusBusy=true;lastStatus=Date.now();const current=host;try{const data=await api('everythingStatus');if(current!==host||!current.isConnected)return;renderActivity(current,data);renderDashboard(current,data);renderMissing(current,data);renderEvents(current,data);const s=data.status||{};current.querySelector('#zain-everything-live').textContent='الحالة: '+(data.enabled?(s.error||s.phase):'المتابعة متوقفة')+(s.path?' — '+s.path:'')+(s.total!=null?' — نتائج الفهرس المقروءة: '+(s.offset||0)+' من '+s.total:'')+' — إضافات مكتملة: '+(s.added||0)+' — بانتظار الإضافة: '+(s.pending||0);}catch{if(current===host&&current.isConnected){current.querySelector('#zain-everything-live').textContent='تعذر تحديث حالة المتابعة؛ ستعاد المحاولة';const activityBox=current.querySelector('#zain-everything-activity');if(activityBox)delete activityBox.dataset.signature;const icon=current.querySelector('.zain-current-icon');if(icon){icon.className='zain-current-icon error';icon.textContent='!';}const now=current.querySelector('#zain-everything-now');if(now)now.textContent='تعذر تحديث الحالة من الخادم؛ ستعاد المحاولة';}}finally{statusBusy=false;}}
